ALTER TYPE "JobStatus" ADD VALUE IF NOT EXISTS 'IN_PROGRESS';
ALTER TYPE "JobStatus" ADD VALUE IF NOT EXISTS 'COMPLETED';
CREATE TYPE "TransactionStatus" AS ENUM ('PENDING','IN_PROGRESS','COMPLETED','CANCELLED');
CREATE TYPE "NotificationType" AS ENUM ('APPLICATION','JOB','MESSAGE','PAYMENT','PREMIUM','TRANSACTION','SYSTEM');
CREATE TABLE "Profile" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"headline" TEXT,"location" TEXT,"website" TEXT,"availability" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Profile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Profile_userId_key" ON "Profile"("userId"); ALTER TABLE "Profile" ADD CONSTRAINT "Profile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Job" ADD COLUMN IF NOT EXISTS "hiredFreelancerId" TEXT, ADD COLUMN IF NOT EXISTS "startedAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "completedAt" TIMESTAMP(3);
CREATE TABLE "Transaction" ("id" TEXT NOT NULL,"jobId" TEXT NOT NULL,"clientId" TEXT NOT NULL,"freelancerId" TEXT NOT NULL,"grossAmount" INTEGER NOT NULL,"commissionRate" INTEGER NOT NULL DEFAULT 15,"commissionAmount" INTEGER NOT NULL,"freelancerAmount" INTEGER NOT NULL,"status" "TransactionStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "Transaction_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Transaction_jobId_key" ON "Transaction"("jobId"); CREATE INDEX "Transaction_status_createdAt_idx" ON "Transaction"("status","createdAt");
ALTER TABLE "Transaction" ADD CONSTRAINT "Transaction_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Transaction" ADD CONSTRAINT "Transaction_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Transaction" ADD CONSTRAINT "Transaction_freelancerId_fkey" FOREIGN KEY ("freelancerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "Notification" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" "NotificationType" NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"link" TEXT,"read" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Notification_pkey" PRIMARY KEY ("id")); CREATE INDEX "Notification_userId_read_createdAt_idx" ON "Notification"("userId","read","createdAt"); ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "AIConversation" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"title" TEXT NOT NULL DEFAULT 'New conversation',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AIConversation_pkey" PRIMARY KEY ("id")); CREATE INDEX "AIConversation_userId_updatedAt_idx" ON "AIConversation"("userId","updatedAt"); ALTER TABLE "AIConversation" ADD CONSTRAINT "AIConversation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "AIMessage" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"role" TEXT NOT NULL,"content" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AIMessage_pkey" PRIMARY KEY ("id")); CREATE INDEX "AIMessage_conversationId_createdAt_idx" ON "AIMessage"("conversationId","createdAt"); ALTER TABLE "AIMessage" ADD CONSTRAINT "AIMessage_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "AIConversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
